INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The Mid-Autumn Festival', 'The Mid-Autumn Festival is one of the most important festivals in China. It falls on the fifteenth day of the eighth lunar month, usually in September or October. On this day, the moon is round and bright. Chinese people believe that a round moon means family reunion, so families try to get together on this night. They sit in the yard, look at the full moon and eat mooncakes. Mooncakes are round and sweet, with many different fillings. Children also love the old story of Chang''e, the lady who flew to the moon. The festival is a happy time for families to share love and good food.', '说明文', 107, '[{"q": "When does the Mid-Autumn Festival fall?", "answer": "B", "options": ["On October 1st.", "On the 15th day of the 8th lunar month.", "On December 25th.", "On the first day of the year."], "explanation": "见原文对应句"}, {"q": "What does a round moon mean to Chinese people?", "answer": "B", "options": ["Good weather.", "Family reunion.", "A new year.", "Hard work."], "explanation": "见原文对应句"}, {"q": "What do families do on this night?", "answer": "D", "options": ["Watch dragon boat races.", "Throw water at each other.", "Give red packets.", "Look at the full moon and eat mooncakes."], "explanation": "见原文对应句"}, {"q": "What are mooncakes like?", "answer": "D", "options": ["Long and salty.", "Hot and spicy.", "Green and sour.", "Round and sweet with different fillings."], "explanation": "见原文对应句"}, {"q": "Whose story do children love?", "answer": "A", "options": ["Chang''e''s.", "Qu Yuan''s.", "Santa''s.", "The Monkey King''s."], "explanation": "见原文对应句"}]'::jsonb, '[{"word": "reunion", "cn": "团聚;团圆"}, {"word": "filling", "cn": "馅"}, {"word": "lunar", "cn": "农历的"}]'::jsonb, 3, 'g9', 'U2');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Tom''s First Spring Festival', 'Last winter, Tom, an exchange student from London, spent his first Spring Festival in a small Chinese village. His friend Lin invited him home for the holiday. On New Year''s Eve, the whole family cleaned the house and put up red couplets on the doors. In the evening, they made dumplings together and watched the Spring Festival show on TV. At midnight, Tom heard firecrackers outside and saw the sky full of light. The next morning, Lin''s grandparents gave the children red packets with money inside. Tom was very surprised and happy. He said it was the most exciting festival he had ever had.', '记叙文', 104, '[{"q": "Where is Tom from?", "answer": "B", "options": ["Sydney.", "London.", "New York.", "Tokyo."], "explanation": "见原文对应句"}, {"q": "Where did Tom spend Spring Festival?", "answer": "C", "options": ["In a big city.", "At school.", "In a small Chinese village.", "In London."], "explanation": "见原文对应句"}, {"q": "What did the family do on New Year''s Eve?", "answer": "A", "options": ["Cleaned the house and made dumplings.", "Watched a film at the cinema.", "Went swimming.", "Visited a museum."], "explanation": "见原文对应句"}, {"q": "What did the grandparents give the children?", "answer": "A", "options": ["Red packets with money.", "Books and pens.", "New clothes.", "Toy cars."], "explanation": "见原文对应句"}, {"q": "How did Tom feel about the festival?", "answer": "A", "options": ["It was the most exciting one he had ever had.", "It was boring.", "It was too quiet.", "It was scary."], "explanation": "见原文对应句"}]'::jsonb, '[{"word": "couplet", "cn": "对联"}, {"word": "firecracker", "cn": "鞭炮"}, {"word": "red packet", "cn": "红包"}]'::jsonb, 3, 'g9', 'U2');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Spring Festival and Christmas', 'Spring Festival in China and Christmas in the West are both important family festivals, but they have some differences. Both are a time for family: people come home, share a big meal and give presents to each other. However, the dates are different. Spring Festival follows the lunar calendar, so it falls on a different day each year, usually in late January or February. Christmas is always on December 25th. The food is different too. At Spring Festival, Chinese families eat dumplings and fish, while at Christmas many Western families eat turkey. Though the customs are not the same, both festivals carry the same warm wish: happiness for the whole family.', '对比说明', 111, '[{"q": "What do the two festivals have in common?", "answer": "B", "options": ["Both fall on the same day.", "Both are a time for family.", "Both have the same food.", "Both last one month."], "explanation": "见原文对应句"}, {"q": "When is Spring Festival?", "answer": "D", "options": ["Always on December 25th.", "Always in April.", "On October 1st.", "In late January or February."], "explanation": "见原文对应句"}, {"q": "When is Christmas?", "answer": "C", "options": ["On a different day each year.", "In February.", "On December 25th.", "In June."], "explanation": "见原文对应句"}, {"q": "What do many Western families eat at Christmas?", "answer": "A", "options": ["Turkey.", "Dumplings.", "Zongzi.", "Mooncakes."], "explanation": "见原文对应句"}, {"q": "What wish do both festivals carry?", "answer": "D", "options": ["Success at work.", "Good weather.", "More money.", "Happiness for the whole family."], "explanation": "见原文对应句"}]'::jsonb, '[{"word": "calendar", "cn": "日历;历法"}, {"word": "turkey", "cn": "火鸡"}, {"word": "custom", "cn": "风俗;习俗"}]'::jsonb, 3, 'g9', 'U2');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'An Invitation to the Dragon Boat Festival', 'Dear Jack, How are you? I''m writing to invite you to visit my city during the Dragon Boat Festival in June. It is one of the most exciting festivals in China. On that day, people watch dragon boat races by the river. The boats are long and colourful, and the teams row very fast to the sound of drums. We also eat zongzi, sticky rice wrapped in green leaves. My mother makes the best zongzi! The festival remembers an old poet who loved his country. I''m sure you will love the races and the food. Please come and join us! Your friend, Li Hua', '书信', 104, '[{"q": "Why is Li Hua writing the letter?", "answer": "A", "options": ["To invite Jack to the Dragon Boat Festival.", "To say goodbye.", "To borrow money.", "To ask for homework."], "explanation": "见原文对应句"}, {"q": "When is the Dragon Boat Festival?", "answer": "A", "options": ["In June.", "In December.", "In April.", "In September."], "explanation": "见原文对应句"}, {"q": "What do people watch on that day?", "answer": "A", "options": ["Dragon boat races.", "Lantern shows.", "Football matches.", "Films."], "explanation": "见原文对应句"}, {"q": "What is zongzi?", "answer": "B", "options": ["A round sweet cake.", "Sticky rice wrapped in green leaves.", "A kind of soup.", "A green drink."], "explanation": "见原文对应句"}, {"q": "Who does the festival remember?", "answer": "C", "options": ["A famous king.", "A brave soldier.", "An old poet who loved his country.", "A rich businessman."], "explanation": "见原文对应句"}]'::jsonb, '[{"word": "row", "cn": "划(船)"}, {"word": "drum", "cn": "鼓"}, {"word": "poet", "cn": "诗人"}]'::jsonb, 3, 'g9', 'U2');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Why Festivals Still Matter', 'Today some young people think that traditional festivals are old-fashioned. They prefer shopping online or playing games. But traditional festivals still matter a lot. First, they bring families together. In our busy life, festivals give us a reason to go home and meet the people we love. Second, festivals help us remember our culture and history. Through festival food, stories and customs, young people learn where they come from. Finally, festivals make life more colourful and fun. Without them, the year would feel the same from beginning to end. So we should keep our festivals alive and pass them on to the next generation.', '议论文', 104, '[{"q": "What do some young people think about traditional festivals?", "answer": "D", "options": ["They are too expensive.", "They are dangerous.", "They are too short.", "They are old-fashioned."], "explanation": "见原文对应句"}, {"q": "What is the first reason festivals matter?", "answer": "B", "options": ["They save money.", "They bring families together.", "They are easy.", "They are quiet."], "explanation": "见原文对应句"}, {"q": "How do festivals help with culture?", "answer": "A", "options": ["Through festival food, stories and customs.", "By selling things online.", "By playing games.", "By cleaning houses."], "explanation": "见原文对应句"}, {"q": "What would the year feel like without festivals?", "answer": "D", "options": ["Much shorter.", "Much busier.", "More expensive.", "The same from beginning to end."], "explanation": "见原文对应句"}, {"q": "What does the writer suggest?", "answer": "C", "options": ["Stop all festivals.", "Only shop online.", "Keep festivals alive and pass them on.", "Forget old customs."], "explanation": "见原文对应句"}]'::jsonb, '[{"word": "old-fashioned", "cn": "过时的"}, {"word": "generation", "cn": "一代人"}, {"word": "culture", "cn": "文化"}]'::jsonb, 3, 'g9', 'U2');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The Water Festival', 'The Water Festival is the most important festival for the Dai people in Yunnan, China. It also takes place in Thailand and some other countries in April. During the festival, people go out into the streets and throw water at each other. You may get very wet, but no one gets angry. In fact, getting wet is a good thing! People believe that the water washes away bad luck and brings a happy new year. Besides throwing water, people also watch dragon boat races, sing and dance. The Water Festival is a time of joy, and visitors from all over the world come to join the fun.', '应用说明', 107, '[{"q": "Who is the Water Festival most important for?", "answer": "B", "options": ["The British.", "The Dai people.", "The Americans.", "The Japanese."], "explanation": "见原文对应句"}, {"q": "When does it take place?", "answer": "D", "options": ["In December.", "In September.", "In January.", "In April."], "explanation": "见原文对应句"}, {"q": "What do people do during the festival?", "answer": "C", "options": ["Light lanterns.", "Climb mountains.", "Throw water at each other.", "Watch films."], "explanation": "见原文对应句"}, {"q": "Why is getting wet a good thing?", "answer": "D", "options": ["The weather is hot.", "Water is cheap.", "It saves time.", "The water washes away bad luck."], "explanation": "见原文对应句"}, {"q": "Who comes to join the fun?", "answer": "A", "options": ["Visitors from all over the world.", "Only the Dai people.", "Only children.", "Only teachers."], "explanation": "见原文对应句"}]'::jsonb, '[{"word": "bad luck", "cn": "厄运"}, {"word": "join", "cn": "参加;加入"}, {"word": "visitor", "cn": "游客"}]'::jsonb, 3, 'g9', 'U2');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U2', 'The Lantern Festival', 'The Lantern Festival comes on the fifteenth day of the first lunar (1)____, two weeks after Spring Festival. It marks the (2)____ of the New Year celebrations. On this night, the streets are full of beautiful (3)____ in many shapes and colours. Children carry small ones and walk (4)____ the streets happily. Many lanterns have riddles on them, and people try to (5)____ the answers. Families also eat tangyuan, sweet rice (6)____ that are round and soft. The round shape (7)____ family reunion, just like the full moon. Long ago, people lit lanterns to (8)____ for good luck. Today the festival is still very (9)____, and parks hold big lantern shows. It is a (10)____ end to the Spring Festival holiday.', 121, 3, '[{"q": "1", "answer": "D", "options": ["week", "day", "year", "month"], "explanation": "first lunar month 正月"}, {"q": "2", "answer": "C", "options": ["start", "middle", "end", "top"], "explanation": "marks the end 标志结束"}, {"q": "3", "answer": "C", "options": ["books", "cars", "lanterns", "trees"], "explanation": "灯笼"}, {"q": "4", "answer": "B", "options": ["under", "along", "into", "off"], "explanation": "walk along the streets 沿街"}, {"q": "5", "answer": "C", "options": ["throw", "lose", "guess", "cut"], "explanation": "guess the answers 猜谜底"}, {"q": "6", "answer": "D", "options": ["cards", "boxes", "leaves", "balls"], "explanation": "rice balls 汤圆"}, {"q": "7", "answer": "C", "options": ["asks", "stops", "means", "leaves"], "explanation": "圆形象征团圆"}, {"q": "8", "answer": "A", "options": ["hope", "hate", "fear", "fail"], "explanation": "to hope for good luck 祈求好运"}, {"q": "9", "answer": "C", "options": ["empty", "silent", "popular", "quiet"], "explanation": "仍很受欢迎"}, {"q": "10", "answer": "C", "options": ["boring", "scary", "happy", "terrible"], "explanation": "欢乐的结尾"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U2', 'My First Thanksgiving', 'Last November, I stayed with a host (1)____ in the United States and had my first Thanksgiving. Thanksgiving is an important American (2)____. On that day, families get (3)____ to give thanks for the good things in their life. My host mother (4)____ a big dinner. The main dish was a large (5)____, and there were also potatoes and pumpkin pie. Before we (6)____, everyone said what they were thankful (7)____. I said I was thankful for my new friends. The food was (8)____, and I ate too much! After dinner, we (9)____ games and talked for hours. It was a warm evening, and I will never (10)____ my first Thanksgiving.', 111, 3, '[{"q": "1", "answer": "B", "options": ["school", "family", "shop", "team"], "explanation": "host family 寄宿家庭"}, {"q": "2", "answer": "B", "options": ["lesson", "festival", "game", "sport"], "explanation": "美国重要节日"}, {"q": "3", "answer": "C", "options": ["away", "lost", "together", "angry"], "explanation": "get together 团聚"}, {"q": "4", "answer": "A", "options": ["cooked", "washed", "sold", "broke"], "explanation": "cook dinner 做饭"}, {"q": "5", "answer": "D", "options": ["fish", "cake", "soup", "turkey"], "explanation": "火鸡是主菜"}, {"q": "6", "answer": "C", "options": ["slept", "ran", "ate", "left"], "explanation": "before we ate 吃饭前"}, {"q": "7", "answer": "C", "options": ["at", "in", "for", "on"], "explanation": "thankful for 感激"}, {"q": "8", "answer": "C", "options": ["terrible", "ugly", "delicious", "empty"], "explanation": "食物美味"}, {"q": "9", "answer": "B", "options": ["lost", "played", "missed", "stopped"], "explanation": "play games 玩游戏"}, {"q": "10", "answer": "D", "options": ["clean", "sell", "miss", "forget"], "explanation": "never forget 永不忘"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U2', 'Our Culture Festival', 'Last Friday, our school held an International Culture (1)____. Each class showed the festivals of a different (2)____. My class chose China. We made paper (3)____ and wrote Spring Festival couplets. The students in Class Two showed Christmas, with a big green (4)____ and small gifts. Another class (5)____ everyone an Indian dance. The hall was full of music, colour and (6)____ food from around the world. I (7)____ a sweet rice cake from the Japan booth — it was new to me but very nice. Through the festival, we (8)____ a lot about other cultures. We also felt (9)____ of our own traditions. Everyone agreed it was the best school (10)____ of the year.', 115, 3, '[{"q": "1", "answer": "B", "options": ["lesson", "Festival", "exam", "match"], "explanation": "文化节"}, {"q": "2", "answer": "A", "options": ["country", "school", "family", "year"], "explanation": "不同国家"}, {"q": "3", "answer": "C", "options": ["cars", "boats", "lanterns", "planes"], "explanation": "纸灯笼"}, {"q": "4", "answer": "B", "options": ["box", "tree", "bell", "star"], "explanation": "Christmas tree 圣诞树"}, {"q": "5", "answer": "C", "options": ["sold", "bought", "taught", "threw"], "explanation": "teach a dance 教舞蹈"}, {"q": "6", "answer": "B", "options": ["ugly", "tasty", "empty", "silent"], "explanation": "美味的食物"}, {"q": "7", "answer": "C", "options": ["threw", "lost", "tried", "broke"], "explanation": "try food 品尝"}, {"q": "8", "answer": "A", "options": ["learned", "forgot", "lost", "missed"], "explanation": "learn about 了解"}, {"q": "9", "answer": "B", "options": ["afraid", "proud", "tired", "bored"], "explanation": "proud of 自豪"}, {"q": "10", "answer": "B", "options": ["exam", "event", "rule", "problem"], "explanation": "最棒的活动"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U2', 'A Christmas Morning', 'On Christmas (1)____, my sister and I woke up very early. We ran to the living room and saw a big Christmas (2)____ with colourful lights. Under it, there were many (3)____ wrapped in shiny paper. We could not (4)____ to open them! I got a new book, and my sister got a beautiful (5)____. We said "Thank you" to our parents and gave them our cards. Then the whole family had a big (6)____ together. My mother had cooked a turkey, and the kitchen smelled (7)____. After lunch, we sang Christmas (8)____ and called our grandparents to say "(9)____ Christmas". It was a warm and (10)____ day that I will always remember.', 113, 3, '[{"q": "1", "answer": "B", "options": ["night", "morning", "week", "year"], "explanation": "圣诞节早晨"}, {"q": "2", "answer": "D", "options": ["box", "car", "wall", "tree"], "explanation": "圣诞树"}, {"q": "3", "answer": "C", "options": ["problems", "lessons", "presents", "rules"], "explanation": "礼物"}, {"q": "4", "answer": "C", "options": ["run", "sleep", "wait", "cry"], "explanation": "could not wait 迫不及待"}, {"q": "5", "answer": "D", "options": ["knife", "stone", "brick", "doll"], "explanation": "洋娃娃"}, {"q": "6", "answer": "B", "options": ["game", "meal", "test", "trip"], "explanation": "a big meal 大餐"}, {"q": "7", "answer": "D", "options": ["terrible", "empty", "silent", "wonderful"], "explanation": "smell wonderful 香"}, {"q": "8", "answer": "A", "options": ["songs", "books", "games", "cards"], "explanation": "Christmas songs 圣诞歌"}, {"q": "9", "answer": "A", "options": ["Merry", "sad", "angry", "late"], "explanation": "Merry Christmas 圣诞快乐"}, {"q": "10", "answer": "B", "options": ["boring", "happy", "scary", "sad"], "explanation": "温暖快乐的一天"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U2', 'My First Halloween', 'When I was studying in Canada, I (1)____ my first Halloween on October 31st. In the afternoon, my friends and I made lanterns from big orange (2)____. We cut funny faces on them and put a light (3)____. In the evening, we put on scary (4)____. I dressed up as a black cat! Then we went from house to (5)____ in our neighbourhood. At each door, we said "Trick or (6)____!" and people gave us sweets. Soon my bag was (7)____ of candy. Some houses looked really (8)____, with fake spiders and ghosts. At first I was a little (9)____, but it was actually great fun. Halloween is a (10)____ festival, and I enjoyed every minute of it.', 118, 3, '[{"q": "1", "answer": "D", "options": ["lost", "missed", "sold", "celebrated"], "explanation": "过节"}, {"q": "2", "answer": "B", "options": ["apples", "pumpkins", "oranges", "potatoes"], "explanation": "南瓜"}, {"q": "3", "answer": "D", "options": ["outside", "away", "off", "inside"], "explanation": "put a light inside 里面放灯"}, {"q": "4", "answer": "A", "options": ["costumes", "books", "songs", "games"], "explanation": "scary costumes 吓人服装"}, {"q": "5", "answer": "B", "options": ["school", "house", "river", "hill"], "explanation": "house to house 挨家挨户"}, {"q": "6", "answer": "A", "options": ["treat", "trip", "team", "test"], "explanation": "Trick or treat 不给糖就捣蛋"}, {"q": "7", "answer": "D", "options": ["free", "short", "late", "full"], "explanation": "full of candy 装满糖"}, {"q": "8", "answer": "A", "options": ["scary", "lovely", "quiet", "empty"], "explanation": "房子很吓人"}, {"q": "9", "answer": "C", "options": ["proud", "tired", "afraid", "sure"], "explanation": "起初有点害怕"}, {"q": "10", "answer": "B", "options": ["boring", "fun", "sad", "terrible"], "explanation": "有趣的节日"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U2', 'A Mid-Autumn Reunion', 'Every year on Mid-Autumn night, my family has a big reunion (1)____. This year my aunt came back from far away, so everyone was very (2)____. After dinner, we carried chairs into the (3)____ and sat under the night sky. The moon was round and (4)____, the brightest I had ever seen. We ate (5)____ together, and each one had a different filling. My grandfather told us the old (6)____ of Chang''e flying to the moon. My little cousin listened with wide (7)____. We also took many photos to (8)____ this happy moment. My mother said the round moon (9)____ that our family is always together, even when we are far (10)____. It was a perfect night.', 117, 3, '[{"q": "1", "answer": "B", "options": ["exam", "dinner", "game", "trip"], "explanation": "团圆饭"}, {"q": "2", "answer": "C", "options": ["angry", "tired", "happy", "sad"], "explanation": "非常高兴"}, {"q": "3", "answer": "D", "options": ["river", "school", "shop", "garden"], "explanation": "院子里"}, {"q": "4", "answer": "B", "options": ["dark", "bright", "small", "empty"], "explanation": "又圆又亮"}, {"q": "5", "answer": "A", "options": ["mooncakes", "dumplings", "noodles", "bread"], "explanation": "吃月饼"}, {"q": "6", "answer": "D", "options": ["song", "game", "rule", "story"], "explanation": "嫦娥的故事"}, {"q": "7", "answer": "C", "options": ["ears", "hands", "eyes", "feet"], "explanation": "with wide eyes 睁大眼睛"}, {"q": "8", "answer": "A", "options": ["remember", "forget", "lose", "sell"], "explanation": "to remember 记住此刻"}, {"q": "9", "answer": "A", "options": ["means", "asks", "stops", "hopes"], "explanation": "圆月象征团圆"}, {"q": "10", "answer": "D", "options": ["ago", "along", "off", "apart"], "explanation": "far apart 远隔"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U2 听力·对话 Watching the Dragon Boat Races', '九上 Unit2 听力·节日', 2, 'Mike: Anna, the Dragon Boat Festival is this Saturday. Do you want to watch the races with me?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U2 听力·短文 How My Family Celebrates Spring Festival', '九上 Unit2 听力·节日', 2, 'Spring Festival is my favourite time of the year. A few days before it, my family cleans the whole house to sweep away bad luck. We also put up red couplets on the door. On New Year''s Eve, all my relatives come to my grandparents'' home for a big dinner. We always eat dumplings and fish, because they bring good luck. After dinner, we watch the festival show on TV and wait for midnight. The best part for me is the red packets. My parents and grandparents give us money in red envelopes. The next day, we visit our relatives and say "Happy New Year".', '春节是“我”最爱的节日。节前几天全家大扫除扫走霉运、贴红春联;除夕亲戚到爷爷奶奶家吃年夜饭,吃饺子和鱼(寓意好运);饭后看春晚守岁;最爱红包(长辈给压岁钱);第二天走亲戚拜年。', 'us_female', '[{"q": "What does the family do a few days before Spring Festival?", "type": "choice", "answer": "D", "options": ["Buy a new car.", "Travel abroad.", "Plant trees.", "Clean the whole house."]}, {"q": "Where do the relatives gather on New Year''s Eve?", "type": "choice", "answer": "B", "options": ["At a restaurant.", "At the grandparents'' home.", "At the speaker''s school.", "At the park."]}, {"q": "What do they eat for good luck?", "type": "choice", "answer": "C", "options": ["Turkey and pie.", "Mooncakes.", "Dumplings and fish.", "Zongzi."]}, {"q": "What is the speaker''s favourite part?", "type": "choice", "answer": "B", "options": ["The cleaning.", "The red packets.", "The TV show.", "The couplets."]}, {"q": "What do they do the next day?", "type": "choice", "answer": "C", "options": ["Go back to school.", "Clean again.", "Visit relatives and say Happy New Year.", "Watch races."]}]'::jsonb, '[]'::jsonb, 'short', 'g9', 'U2');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U2 听力·对话 Asking about the Mid-Autumn Festival', '九上 Unit2 听力·节日', 2, 'Sam: Hi, Mei. What festival is coming soon?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U2 听力·短文 My Water Festival Day', '九上 Unit2 听力·节日', 2, 'Last April, I visited Yunnan during the Water Festival of the Dai people. It was the most fun day of my trip. In the morning, everyone went into the streets carrying bowls and buckets of water. Then the water fight began! People threw water at each other and laughed. Soon I was wet from head to foot, but I didn''t mind at all. The Dai people say that the water washes away bad luck and brings happiness. In the afternoon, we watched dragon boat races and saw beautiful dances. By evening, I was tired but very happy. I will never forget the day I got soaked at the Water Festival.', '去年四月“我”在云南赶上傣族泼水节,是旅途中最开心的一天。早上人们提着碗和桶上街,泼水大战开始,互相泼水欢笑;很快全身湿透但毫不在意;傣族人说水能洗去霉运、带来幸福;下午看龙舟赛和舞蹈;傍晚虽累但很开心,永远忘不了被泼湿的这天。', 'us_female', '[{"q": "Where did the speaker go?", "type": "choice", "answer": "D", "options": ["Thailand.", "Beijing.", "London.", "Yunnan."]}, {"q": "When was it?", "type": "choice", "answer": "D", "options": ["Last December.", "Last September.", "Last June.", "Last April."]}, {"q": "What did people throw at each other?", "type": "choice", "answer": "B", "options": ["Flowers.", "Water.", "Sweets.", "Paper."]}, {"q": "What do the Dai people believe the water does?", "type": "choice", "answer": "B", "options": ["Makes people rich.", "Washes away bad luck and brings happiness.", "Keeps people cool only.", "Cleans the streets."]}, {"q": "How did the speaker feel by evening?", "type": "choice", "answer": "A", "options": ["Tired but very happy.", "Angry and wet.", "Bored and cold.", "Sad and tired."]}]'::jsonb, '[]'::jsonb, 'short', 'g9', 'U2');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U2 听力·对话 Our Favourite Festivals', '九上 Unit2 听力·节日', 2, 'Lily: What''s your favourite festival, Ben?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U2 听力·短文 Making Zongzi with Grandma', '九上 Unit2 听力·节日', 2, 'Last year, before the Dragon Boat Festival, my grandma taught me how to make zongzi. First, we washed the green leaves and the sticky rice. Then Grandma showed me how to fold the leaves into a small cup. We put rice and a sweet red date inside, and tied it up with string. My first zongzi looked ugly, and the rice fell out! But Grandma was patient, and I tried again and again. By the end, I could make nice ones. When we ate them together, I felt very proud. Making zongzi with Grandma is my best festival memory, because I learned a skill and spent happy time with her.', '去年端午前,奶奶教“我”包粽子。先洗粽叶和糯米;奶奶教把叶子折成小杯,放米和一颗甜红枣,用绳扎好;“我”第一个包得很丑、米还漏出来,但奶奶很耐心,反复练后能包好了;一起吃时很自豪。和奶奶包粽子是最美的节日记忆——学会一项技能又和她共度快乐时光。', 'us_female', '[{"q": "Which festival was coming?", "type": "choice", "answer": "B", "options": ["The Lantern Festival.", "The Dragon Boat Festival.", "Christmas.", "The Water Festival."]}, {"q": "Who taught the speaker to make zongzi?", "type": "choice", "answer": "D", "options": ["Mum.", "A teacher.", "A friend.", "Grandma."]}, {"q": "What did they put inside the zongzi?", "type": "choice", "answer": "D", "options": ["Meat and salt.", "Nuts and sugar.", "Fish and leaves.", "Rice and a sweet red date."]}, {"q": "What happened to the first zongzi?", "type": "choice", "answer": "D", "options": ["It was perfect.", "It was too big.", "It tasted salty.", "It looked ugly and the rice fell out."]}, {"q": "Why is it the speaker''s best festival memory?", "type": "choice", "answer": "A", "options": ["She learned a skill and spent happy time with Grandma.", "She won a prize.", "She got money.", "She went travelling."]}]'::jsonb, '[]'::jsonb, 'short', 'g9', 'U2');
INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'My Favourite Festival', '以 “My Favourite Festival(我最喜欢的节日)” 为题写约 80 词短文。要点:写出节日名称与时间；人们做什么、吃什么；你为什么喜欢它；用本单元句型:宾语从句 I think/believe that… + 感叹句 What…!/How…!', 'Write a short passage on the topic: "My Favourite Festival".', '["写出节日名称与时间", "人们做什么、吃什么", "你为什么喜欢它", "用本单元句型:宾语从句 I think/believe that… + 感叹句 What…!/How…!"]'::jsonb, 70, 100, 'My favourite festival is the Mid-Autumn Festival. It usually comes in September or October. On that day, my family gets together and has a big dinner. We eat mooncakes and look at the full moon. I think that the round moon is a symbol of family reunion. What a beautiful night it is! I like this festival because I can spend happy time with the people I love. I believe that traditional festivals make our life warmer and more colourful.', '【15分制】A(13-15):要点全、正确用宾语从句+感叹句、语法基本无误;B(10-12):较全、少量错误;C(7-9):要点偏少、句型简单;D(0-6):不完整、错误多。', 3, 'My Favourite Festival', '["My favourite festival is the Mid-Autumn Festival.（我最喜欢的节日是中秋节。）", "On that day, my family gets together.（那天全家团聚。）", "I think that the festival brings us closer.（我认为这个节日让我们更亲近。）", "What a wonderful festival it is!（多么美好的节日啊!）", "How happy we are on this day!（这一天我们多开心啊!）", "I believe that traditional festivals are important.（我相信传统节日很重要。）"]'::jsonb, '[{"wrong": "What a delicious food!", "correct": "What delicious food!", "note": "food 不可数,What 后不加 a。"}, {"wrong": "How a beautiful day!", "correct": "What a beautiful day!", "note": "day 是单数可数名词,用 What a + 名词。"}, {"wrong": "I wonder that she will come.", "correct": "I wonder if she will come.", "note": "嵌入一般疑问句用 if/whether,不用 that。"}]'::jsonb, '【段落结构】第1段:点题——My favourite festival is …，时间。
